Input: {"question": "When was the Museum of Applied Arts established?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0171-cd88d9fb829c:d00", "start": 0, "end": 26, "text": "with around 60,000 titles."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0171-cd88d9fb829c:d00", "start": 27, "end": 114, "text": "The museum was founded in 1874 as the \"Kunstgewerbemuseum\" (Museum of Arts and Crafts)."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0171-cd88d9fb829c:d00", "start": 115, "end": 184, "text": "It moved into its present location, the New Grassi Building, in 1926."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0171-cd88d9fb829c:d00", "start": 185, "end": 247, "text": "Numerous exhibits were destroyed by bombs during World War II."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0171-cd88d9fb829c:d00", "start": 248, "end": 342, "text": "Between 1981 and 1994, no permanent exhibition was possible because of damage to the building."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0171-cd88d9fb829c:d00", "start": 343, "end": 395, "text": "The Grassi Museum was refurbished from 2001 to 2006."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0171-cd88d9fb829c:d00", "start": 396, "end": 506, "text": "The Museum of Applied Arts received its present name in 2005, and the new permanent exhibition opened in 2007."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0171-cd88d9fb829c:d00", "start": 507, "end": 610, "text": "The museum is one of around 20 so-called \"Cultural Lighthouses\" in the German government's Blue Book of"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0171-cd88d9fb829c:d01", "start": 0, "end": 97, "text": "Museum of Applied Arts (Budapest) The Museum of Applied Arts () is a museum in Budapest, Hungary."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0171-cd88d9fb829c:d01", "start": 98, "end": 154, "text": "It is the third-oldest applied arts museum in the world."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0171-cd88d9fb829c:d01", "start": 155, "end": 184, "text": "The architect is Art Nouveau."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0171-cd88d9fb829c:d01", "start": 185, "end": 253, "text": "It was built between 1893 and 1896 and was designed by Ödön Lechner."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0171-cd88d9fb829c:d01", "start": 254, "end": 343, "text": "It has a green roof and the interior is designed using Hindu, Mogul, and Islamic designs."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0171-cd88d9fb829c:d01", "start": 344, "end": 419, "text": "The building is in need of renovation, for which plans have been developed."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0171-cd88d9fb829c:d01", "start": 420, "end": 496, "text": "The museum houses a collection of metalwork, furniture, textiles, and glass."}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0171-cd88d9fb829c:d01", "start": 497, "end": 519, "text": "It also has a library."}, "D2S9": {"document_number": 2, "doc_id": "ramdocs-0171-cd88d9fb829c:d01", "start": 520, "end": 576, "text": "There are two other locations: the Hopp Ferenc Museum of"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0171-cd88d9fb829c:d02", "start": 0, "end": 73, "text": "is also showcasing a selection of the museum ’ s Art Nouveau collection ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0171-cd88d9fb829c:d02", "start": 74, "end": 90, "text": "Üllői út 33-37 ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0171-cd88d9fb829c:d02", "start": 91, "end": 588, "text": "1091 Budapest Hungary imm.hu View of the main Museum building designed by Ödön Lechner and Gyula Pártos 1893-1896©Museum of Applied Arts Floor vase designed by Georges de Feure , execution by Jakab Rapoport , Budapest and Paris , c.1902©Museum of Applied Arts Budapest Museum of Applied Arts logo©Museum of Applied Arts György Ráth Villa ©Museum of Applied Arts Other museums to discover The American Museum of Ceramic Art Museum Located in Los Angeles , The American Museum of Ceramic Art ( AMOCA"}}, "original_cards": [{"doc_id": "ramdocs-0171-cd88d9fb829c:d00", "card_id": "ramdocs-0171-cd88d9fb829c:d00:c0", "entity": "Museum of Applied Arts", "scope": "establishment", "claim": "The Museum of Applied Arts was established in 1874.", "answer": "1874", "quote": "The museum was founded in 1874 as the \"Kunstgewerbemuseum\" (Museum of Arts and Crafts).", "original_document_number": 1}, {"doc_id": "ramdocs-0171-cd88d9fb829c:d02", "card_id": "ramdocs-0171-cd88d9fb829c:d02:c0", "entity": "Museum of Applied Arts", "scope": "establishment", "claim": "The Museum of Applied Arts was established between 1893-1896.", "answer": "1893-1896", "quote": "1091 Budapest Hungary imm.hu View of the main Museum building designed by Ödön Lechner and Gyula Pártos 1893-1896©Museum of Applied Arts Floor vase designed by Georges de Feure , execution by Jakab Rapoport , Budapest and Paris , c.1902©Museum of Applied Arts Budapest Museum of Applied Arts logo©Museum of Applied Arts György Ráth Villa ©Museum of Applied Arts Other museums to discover The American Museum of Ceramic Art Museum Located in Los Angeles , The American Museum of Ceramic Art ( AMOCA", "original_document_number": 3}], "current_answers": ["1874", "1893-1896"], "candidate_answers": [{"candidate_id": "R0", "answer": "1874", "origin": "initial"}, {"candidate_id": "R1", "answer": "1893-1896", "origin": "initial"}]}
